'use strict';
const C=window.COURSE,$=s=>document.querySelector(s),KEY='kesit-stat-v1',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(x,d=3)=>x===null?'Tanımsız':Number(x).toLocaleString('tr-TR',{maximumFractionDigits:d});
let state={version:1,role:'analist',answers:{},read:[],last:'s01'},storageError='',tab='learn',search='',level='all',moduleFilter='all',labMode='summary',labData='4 5 5 6 6 7 8 9 10 20',labY='9 11 10 13 15 14 18 19 22 39';
function validState(s){return s&&s.version===1&&(C.roles.some(r=>r.id===s.role)||Object.hasOwn(C.legacyRoles,s.role))&&s.answers&&typeof s.answers==='object'&&!Array.isArray(s.answers)&&Object.entries(s.answers).every(([k,v])=>/^s\d{2,3}-(0|1|2)$/.test(k)&&C.lessons.some(l=>l.id===k.split('-')[0])&&v===true)&&Array.isArray(s.read)&&s.read.every(id=>C.lessons.some(l=>l.id===id))&&C.lessons.some(l=>l.id===s.last)&&(!s.notes||(typeof s.notes==='object'&&!Array.isArray(s.notes)&&Object.entries(s.notes).every(([k,v])=>C.lessons.some(l=>l.id===k)&&typeof v==='string'&&v.length<=20000)))}
try{let raw=localStorage.getItem(KEY);if(raw){let s=JSON.parse(raw);if(!validState(s))throw Error('format');state=s;state.role=C.legacyRoles[state.role]||state.role}}catch(e){storageError='Bu cihazdaki ilerleme kaydı okunamadı. Kayıt üzerine yazılmadı. İlerlemem sayfasından ham kaydı indirebilir veya geçerli bir yedek yükleyebilirsin.'}
function save(){if(storageError)return false;try{localStorage.setItem(KEY,JSON.stringify(state));try{localStorage.setItem('kesit.ozet.istatistik',JSON.stringify({bitti:C.lessons.filter(l=>[0,1,2].every(i=>state.answers[l.id+'-'+i])).length,toplam:C.lessons.length}))}catch(e){}return true}catch(e){storageError='Tarayıcıya kayıt yapılamadı. İlerlemeni yedek olarak indir; bu oturumdaki çalışmaların bellekte tutuluyor.';toast(storageError);return false}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function mastered(l){return [0,1,2].every(i=>state.answers[l.id+'-'+i])}function total(){return C.lessons.filter(mastered).length}function role(){return C.roles.find(r=>r.id===state.role)}function routeLessons(){return role().modules.flatMap(m=>C.lessons.filter(l=>l.module===m))}function nextLesson(){return LearningGuide.next(state)}function warning(){return storageError?`<div class="storage-error">${esc(storageError)} <a href="#progress"><u>Kaydı yönet →</u></a></div>`:''}function pageTitle(k,h,p){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${h}</h1><div class="intro">${p}</div></div><span class="pill"><span class="status-dot"></span> Kendi hızında öğren</span></div>`}
const icons=['◫','▥','⋂','∿','⊙','≶','≋','↗','⊞','⌁','⟳','⋈','⌗','◉','∑','θ','≈','ƒ','∫','∿','⇄','◌','R','L','C','T','E','Σ','τ','D'];
function graph(type=0,small=false){let chart='';const axes='<path d="M50 26V178H405" fill="none" stroke="#bdcbb6" stroke-width="1"/><path d="M50 75H405M50 125H405" stroke="#dce4d3" stroke-dasharray="3 5"/>';
if([0,1,6].includes(type))chart=axes+[54,88,125,91,46,22].map((v,i)=>`<rect x="${68+i*51}" y="${178-v}" width="34" height="${v}" fill="${i===2?'#d58455':'#83a373'}" rx="3"/>`).join('')+'<text x="60" y="198">Değer aralıkları</text><text x="55" y="19">Sıklık · şematik</text>';
else if([2,3,4,5,10].includes(type))chart=axes+'<path d="M55 177C100 177 115 160 145 112S186 24 224 39S264 145 310 166S360 177 402 177" fill="none" stroke="#73946a" stroke-width="3"/><path d="M146 178V110C175 59 192 29 224 39S254 114 271 143V178Z" fill="#b7cea0" opacity=".45"/><path d="M211 40V178" stroke="#d58455" stroke-dasharray="4 4"/><text x="55" y="198">Olası değerler</text><text x="55" y="19">Dağılım · şematik</text>';
else if([7,11].includes(type))chart=axes+'<path d="M64 161L388 44" stroke="#d58455" stroke-width="2" stroke-dasharray="6 4"/>'+[[75,150],[108,155],[145,123],[177,131],[210,98],[238,111],[275,70],[304,83],[343,47],[381,58]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="#719268"/>`).join('')+'<text x="55" y="198">Açıklayıcı değişken</text><text x="55" y="19">İlişki · şematik</text>';
else if(type===8)chart='<text x="50" y="23">Karşılaştırma tasarımı · şematik</text><rect x="40" y="70" width="145" height="80" rx="13" fill="#dfebd0"/><rect x="260" y="70" width="145" height="80" rx="13" fill="#f3dfcb"/><text x="65" y="100">A / Referans</text><text x="65" y="126">Aynı ölçüm</text><text x="280" y="100">B / Uygulama</text><text x="280" y="126">Aynı dönem</text><path d="M196 111H245" stroke="#829376"/><text x="152" y="187">Etki + belirsizlik</text>';
else chart=axes+`<path d="M53 140L82 129L111 143L140 111L169 125L198 98L227 110L256 78L285 95L314 62L343 79L372 41L401 58" stroke="#72946b" fill="none" stroke-width="3"/>${type===12?'<path d="M50 43H405M50 160H405" stroke="#d58455" stroke-dasharray="5 4"/>':''}<text x="55" y="198">Zaman / gözlem sırası</text><text x="55" y="19">${type===12?'Süreç sınırları':'Örüntü'} · şematik</text>`;
return `<svg viewBox="0 0 450 218" role="img" aria-label="${esc(C.modules[type]?.title||'Öğrenme')} için şematik görsel; gerçek veri değildir" xmlns="http://www.w3.org/2000/svg"><g fill="#67785c" font-family="Arial,sans-serif" font-size="11">${chart}</g></svg>`}
function moduleCard(i){let m=C.modules[i],ls=C.lessons.filter(l=>l.module===i),done=ls.filter(mastered).length;return `<a class="module-card" href="#lesson/${ls[0].id}"><div class="card-top"><span class="module-icon ${i%3===1?'orange':i%3===2?'blue':''}">${icons[i]}</span><span class="pill">${m.level==='temel'?'Temel':m.level==='orta'?'Orta seviye':'İleri seviye'}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><div class="card-foot"><span>4 ders · 12 alıştırma</span><span>${done?done+'/4 tamamlandı':'Keşfet ↗'}</span></div></a>`}
function home(){return LearningGuide.home(state)}
function caseStudies(r){return BusinessCases.related(r.id)}
function path(){return LearningGuide.path(state)+caseStudies(role())}
function filterLessons(){return C.lessons.filter(l=>(level==='all'||l.level===level)&&(moduleFilter==='all'||l.module===Number(moduleFilter))&&(!search||[l.title,l.body,C.modules[l.module].title].join(' ').toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr'))))}
function filters(){return `<div class="filters"><input aria-label="Konu ara" id="topic-search" type="search" placeholder="Konu, kavram veya yöntem ara…" value="${esc(search)}"><select id="level-filter" aria-label="Seviye"><option value="all">Tüm seviyeler</option>${['temel','orta','ileri'].map(x=>`<option value="${x}" ${level===x?'selected':''}>${x==='temel'?'Temel':x==='orta'?'Orta seviye':'İleri seviye'}</option>`).join('')}</select><select id="module-filter" aria-label="Modül"><option value="all">Tüm modüller</option>${C.modules.map((m,i)=>`<option value="${i}" ${moduleFilter==i?'selected':''}>${m.title}</option>`).join('')}</select></div>`}
function library(){return pageTitle('KONU KÜTÜPHANESİ','İstatistiğin haritası.',`${C.modules.length} modül boyunca kavramı öğren, örneği incele, kendini sına ve görsel özeti yanında götür.`)+`<div class="actions library-scope"><a class="btn" href="#curriculum">Müfredatın kapsamını gör →</a></div>`+filters()+`<div id="filter-results">${libraryResults()}</div>`}
function libraryResults(){let ls=filterLessons(),methods=window.ConceptTeaching.searchMethods(search,level,moduleFilter);if(!ls.length)return methods||'<div class="empty">Bu aramaya uygun ders yok. Filtreyi değiştir veya başka bir kavram dene.</div>';return `<p class="muted" role="status">${ls.length} ders gösteriliyor</p><div class="curriculum-table">${[...new Set(ls.map(l=>l.module))].map(m=>`<section class="module-row"><div class="module-row-head"><span class="level-code ${C.modules[m].level}">${String(m+1).padStart(2,'0')}</span><div><h3>${C.modules[m].title}</h3><p>${C.modules[m].subtitle}</p></div><span class="tag">${C.modules[m].level}</span></div>${ls.filter(l=>l.module===m).map(l=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="check ${mastered(l)?'done':''}">${mastered(l)?'✓':''}</span><div><b>${l.title}</b><small>${l.minutes} dk · ${l.depth} · ${window.ConceptTeaching.core[l.id]?'Rehberli kavram akışı':'3 soru + vaka'}</small></div><span>→</span></a>`).join('')}</section>`).join('')}</div>${methods}`}

